<main>
  <h1>Crear cuenta</h1>
  <p class="intro">Todos los campos son obligatorios, salvo los marcados como opcionales.</p>

  <form id="registro" method="post" novalidate>
    <div class="field">
      <label for="nombre">Nombre completo</label>
      <input type="text" id="nombre" name="nombre" autocomplete="name" required
             aria-describedby="nombre-error">
      <p class="error" id="nombre-error" aria-live="polite"></p>
    </div>

    <div class="field">
      <label for="email">Dirección de correo electrónico</label>
      <input type="email" id="email" name="email" autocomplete="email" inputmode="email"
