             aria-describedby="email-error">
      <p class="error" id="email-error" aria-live="polite"></p>
    </div>

    <div class="field">
      <label for="web">Sitio web <span class="optional">(opcional)</span></label>
      <input type="url" id="web" name="web" autocomplete="url" inputmode="url"
             autocapitalize="off" spellcheck="false" placeholder="https://ejemplo.com"
             aria-describedby="web-error">
      <p class="error" id="web-error" aria-live="polite"></p>
    </div>

    <div class="field">
      <label for="contrasena">Contraseña</label>
      <div class="password-row">
        <input type="password" id="contrasena" name="contrasena" autocomplete="new-password" required
               aria-describedby="contrasena-ayuda contrasena-error">
        <button type="button" class="toggle" id="mostrar-contrasena"
                aria-controls="contrasena" aria-pressed="false">Mostrar</button>
      </div>
      <p class="hint" id="contrasena-ayuda">Mínimo 8 caracteres, con al menos una letra y un número.</p>
      <p class="error" id="contrasena-error" aria-live="polite"></p>
    </div>

    <button type="submit" class="submit">Crear cuenta</button>
  </form>

  <div class="success" id="confirmacion" role="status" tabindex="-1" hidden>
