</main>

<script>
(function () {
  'use strict';

  const form = document.getElementById('registro');
  const campos = ['nombre', 'email', 'web', 'contrasena'].map(function (id) {
    return document.getElementById(id);
  });

  // Añade https:// si la persona escribió la dirección sin protocolo (p. ej. "ejemplo.com").
  function normalizarUrl(valor) {
    const v = valor.trim();
    if (!v) return '';
    return /^https?:\/\//i.test(v) ? v : 'https://' + v;
  }

  function esUrlValida(valor) {
    let url;
    try {
      url = new URL(valor);
    } catch (e) {
      return false;
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return false;
    if (url.username || url.password) return false;
    return /^([a-z0-9-]+\.)+[a-z0-9-]{2,}$/i.test(url.hostname);
  }

  // Cada validador devuelve un mensaje de error, o una cadena vacía si el valor es válido.
  const validadores = {
    nombre: function (valor) {
      const v = valor.trim();
      if (!v) return 'Escribe tu nombre completo.';
      if ((v.match(/\p{L}/gu) || []).length < 2) return 'El nombre debe tener al menos 2 letras.';
      return '';
    },
    email: function (valor) {
      const v = valor.trim();
      if (!v) return 'Escribe tu dirección de correo electrónico.';
      if (v.length > 254 || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)) {
        return 'Introduce un correo válido, por ejemplo nombre@ejemplo.com.';
      }
      return '';
    },
    web: function (valor) {
      const v = normalizarUrl(valor);
      if (!v) return ''; // campo opcional
      if (!esUrlValida(v)) return 'Introduce una dirección web válida, por ejemplo https://ejemplo.com.';
      return '';
    },
    contrasena: function (valor) {
      if (!valor) return 'Escribe una contraseña.';
      if (valor.length < 8) return 'La contraseña debe tener al menos 8 caracteres.';
      if (!/\p{L}/u.test(valor) || !/\d/.test(valor)) {
        return 'La contraseña debe incluir al menos una letra y un número.';
      }
      return '';
    }
  };

  function mostrarError(input, mensaje) {
    const contenedor = input.closest('.field');
    document.getElementById(input.id + '-error').textContent = mensaje;
    contenedor.classList.toggle('invalid', Boolean(mensaje));
    if (mensaje) {
      input.setAttribute('aria-invalid', 'true');
    } else {
      input.removeAttribute('aria-invalid');
    }
  }

  function validarCampo(input) {
    const mensaje = validadores[input.id](input.value);
    mostrarError(input, mensaje);
    return !mensaje;
  }

  // Limpia espacios sobrantes y completa el protocolo de la URL (la contraseña no se toca).
  function normalizarCampo(input) {
    if (input.id === 'web') {
      input.value = normalizarUrl(input.value);
    } else if (input.id !== 'contrasena') {
      input.value = input.value.trim();
    }
  }

  campos.forEach(function (input) {
    // Al salir del campo: valida solo si hay algo escrito o si ya mostraba un error.
    input.addEventListener('blur', function () {
      normalizarCampo(input);
      if (input.value || input.hasAttribute('aria-invalid')) validarCampo(input);
    });
    // Mientras se corrige un campo con error, el mensaje desaparece en cuanto el valor es válido.
    input.addEventListener('input', function () {
      if (input.hasAttribute('aria-invalid')) validarCampo(input);
    });
  });

  const botonMostrar = document.getElementById('mostrar-contrasena');
  const contrasena = document.getElementById('contrasena');
  botonMostrar.addEventListener('click', function () {
    const visible = contrasena.type === 'text';
    contrasena.type = visible ? 'password' : 'text';
    botonMostrar.textContent = visible ? 'Mostrar' : 'Ocultar';
    botonMostrar.setAttribute('aria-pressed', String(!visible));
  });

  form.addEventListener('submit', function (evento) {
    campos.forEach(normalizarCampo);
    const invalidos = campos.filter(function (input) {
      return !validarCampo(input);
    });

    if (invalidos.length > 0) {
      evento.preventDefault();
      invalidos[0].focus();
      return;
    }

    // Con un atributo action, el navegador envía el formulario al servidor de forma normal.
    if (form.hasAttribute('action')) return;

    // Sin action no hay a dónde enviar: se muestra una confirmación local.
    evento.preventDefault();
    const confirmacion = document.getElementById('confirmacion');
    document.getElementById('confirmacion-texto').textContent =
      'Gracias, ' + document.getElementById('nombre').value +
      '. Tus datos son válidos y están listos para enviarse.';
    form.hidden = true;
    confirmacion.hidden = false;
    confirmacion.focus();
  });
})();
</script>
</body>
